2	// Tudo é calculado a partir dos dados reais: se um post ou curtida
3	// for apagado, a pontuação se ajusta sozinha.
4	const db = require('./db');
5	const { PONTOS, CONQUISTAS } = require('./regras');
6	
7	const SQL_STATS = `
8	SELECT u.id, u.nome, u.curso, u.avatar,
9	  (SELECT COUNT(*) FROM posts p WHERE p.usuario_id = u.id) AS posts,
10	  (SELECT COUNT(DISTINCT c.post_id) FROM comentarios c JOIN posts p ON p.id = c.post_id
11	     WHERE c.usuario_id = u.id AND p.usuario_id <> u.id) AS comentarios,
12	  (SELECT COUNT(*) FROM curtidas l JOIN posts p ON p.id = l.post_id
13	     WHERE p.usuario_id = u.id AND l.usuario_id <> u.id) AS curtidas,
14	  (SELECT COUNT(*) FROM medalhas m WHERE m.aluno_id = u.id) AS medalhas,
15	  (SELECT COALESCE(SUM(t.pontos), 0) FROM medalhas m JOIN tipos_medalha t ON t.id = m.tipo_id
16	     WHERE m.aluno_id = u.id) AS pontos_medalhas
17	FROM usuarios u
18	WHERE u.papel = 'aluno'`;
19	
20	function calcular(s) {
21	  const conquistas = CONQUISTAS.filter((c) => s[c.conta] >= c.meta);
22	  const pontosConquistas = conquistas.reduce((soma, c) => soma + c.bonus, 0);
23	  const total =
24	    s.posts * PONTOS.post +
25	    s.comentarios * PONTOS.comentario +
26	    s.curtidas * PONTOS.curtida +
27	    s.pontos_medalhas +
28	    pontosConquistas;
29	  return { ...s, conquistas, pontos_conquistas: pontosConquistas, total };
30	}
31	
32	// Ordena por pontos e numera as posições. Empatados ficam na mesma posição.
33	function posicionar(lista) {
34	  lista.sort((a, b) => b.total - a.total || a.nome.localeCompare(b.nome, 'pt-BR'));
35	  lista.forEach((a, i) => {
36	    a.posicao = i > 0 && lista[i - 1].total === a.total ? lista[i - 1].posicao : i + 1;
37	  });
38	  return lista;
39	}
40	
41	function ranking(curso) {
42	  let lista = db.prepare(SQL_STATS).all().map(calcular);
43	  if (curso) lista = lista.filter((a) => a.curso === curso);
44	  return posicionar(lista);
45	}
46	
47	// O ranking geral e o de cada curso de uma vez só (uma consulta ao banco).
48	function rankings() {
49	  const geral = ranking();
50	  const porCurso = {};
51	  for (const a of geral) (porCurso[a.curso] ??= []).push({ ...a });
52	  for (const lista of Object.values(porCurso)) posicionar(lista);
53	  return { geral, porCurso };
54	}
55	
56	function statsDoAluno(id) {
57	  const row = db.prepare(SQL_STATS + ' AND u.id = ?').get(id);
58	  if (!row) return null;
59	  const s = calcular(row);
60	  s.posicao_geral = ranking().find((a) => a.id === id)?.posicao;
61	  s.posicao_curso = s.curso ? ranking(s.curso).find((a) => a.id === id)?.posicao : null;
62	  return s;
63	}
64	
65	// Registra as conquistas que o aluno acabou de desbloquear (para aparecerem no feed).
66	// Conquistas já registradas são ignoradas; se o aluno perder uma depois
67	// (ex.: apagou posts), o registro fica como histórico.
68	function registrarConquistas(alunoId, anunciar = true) {
69	  const row = db.prepare(SQL_STATS + ' AND u.id = ?').get(alunoId);
70	  if (!row) return;
71	  const inserir = db.prepare('INSERT OR IGNORE INTO conquistas_alunos (aluno_id, conquista, anunciar) VALUES (?, ?, ?)');
72	  for (const c of calcular(row).conquistas) inserir.run(alunoId, c.id, anunciar ? 1 : 0);
73	}
74	
75	// Na primeira vez com esta versão, registra as conquistas que os alunos já tinham,
76	// sem anunciar no feed (senão o feed seria inundado de conquistas antigas).
77	if (db.prepare('PRAGMA user_version').get().user_version < 1) {
78	  for (const { id } of db.prepare("SELECT id FROM usuarios WHERE papel = 'aluno'").all()) registrarConquistas(id, false);
79	  db.exec('PRAGMA user_version = 1');
80	}
81	
82	module.exports = { ranking, rankings, statsDoAluno, registrarConquistas };
